<x-layout title="Assess public contact"><a class="text-link mb-6 inline-flex gap-2 text-xs" href="{{ route('inquiries.show',$inquiry) }}"><x-icon name="arrow-left" />{{ $inquiry->reference }}</a><x-page-header title="Assess the client & contact" eyebrow="Source identity assessment" description="Review customer-supplied details and explicitly select or create a client record." /><div class="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_320px]"><div class="min-w-0 space-y-6">@if($inquiry->publicSubmission) @include('inquiries.public-evidence') @else @include('mail.intake-evidence') @endif<form class="panel panel-pad space-y-6" method="POST" action="{{ route('inquiries.public-contact.update',$inquiry) }}" data-resolve-client data-unsaved>@csrf @method('PATCH')<input type="hidden" name="lock_version" value="{{ old('lock_version',$inquiry->lock_version) }}"><h2 class="section-title">Working contact details</h2><p class="text-xs leading-6 text-slate-500">Corrections here preserve the original submission. Changing the working email invalidates its mailbox confirmation. Existing directory contacts are never updated by this form.</p><div class="grid gap-5 sm:grid-cols-2">@foreach(['name'=>'Contact name','email'=>'Working email','company'=>'Company','phone'=>'Phone'] as $key=>$label)<x-field :name="'contact['.$key.']'" :label="$label" :value="$inquiry->public_contact[$key]??''" :type="$key==='email'?'email':'text'" :required="in_array($key,['name','email'])" :maxlength="$key==='phone'?64:($key==='company'?255:($key==='email'?254:120))" />@endforeach</div><x-field name="resolution" label="Staff resolution" type="select" required><option value="defer" @selected(old('resolution',$inquiry->client_id?'existing':'defer')==='defer')>Correct details only · defer identity assessment</option><option value="existing" @selected(old('resolution',$inquiry->client_id?'existing':'defer')==='existing')>Select an existing client and contact</option><option value="new_contact" @selected(old('resolution')==='new_contact')>Create a contact for the selected client</option><option value="new_client" @selected(old('resolution')==='new_client')>Create a client and contact from assessed details</option></x-field><x-field name="client_id" label="Existing client" type="select"><option value="">Choose a client (required unless creating a new client)</option>@foreach($clients as $client)<option value="{{ $client->id }}" @selected(old('client_id',$inquiry->client_id)==$client->id)>{{ $client->company_name }}</option>@endforeach</x-field><x-field name="client_contact_id" label="Existing contact" type="select"><option value="">Choose a contact (required for existing selection)</option>@foreach($clients as $client)@foreach($client->contacts->where('is_active',true) as $contact)<option value="{{ $contact->id }}" data-client="{{ $client->id }}" @selected(old('client_contact_id',$inquiry->client_contact_id)==$contact->id)>{{ $client->company_name }} · {{ $contact->name }} · {{ $contact->email }}</option>@endforeach @endforeach</x-field><label class="flex items-start gap-3 text-sm leading-6"><input class="mt-1 h-4 w-4 accent-accent" type="checkbox" name="identity_assessed" value="1" @checked(old('identity_assessed'))>I have assessed the client identity and authorize this directory selection or creation (required when selecting or creating).</label>@error('identity_assessed')<p class="field-error">{{ $message }}</p>@enderror<x-button>Save staff assessment</x-button></form></div><aside class="space-y-6">@if($inquiry->publicSubmission)<section class="panel panel-pad"><h2 class="text-base">Mailbox access check</h2><p class="mt-3 text-sm">{{ $inquiry->mailboxConfirmed()?'Confirmed for the current working email':'Unverified for the current working email' }}</p><p class="mt-3 break-all text-xs text-slate-500">{{ $inquiry->public_contact['email'] }}</p><p class="mt-3 text-xs leading-6">{{ $inquiry->mailboxVerifications()->first()?->label() }}</p><form method="POST" class="mt-5" action="{{ route('inquiries.public-contact.resend',$inquiry) }}">@csrf<input type="hidden" name="lock_version" value="{{ $inquiry->lock_version }}"><x-button variant="secondary" class="w-full">Request confirmation email</x-button></form><p class="mt-3 text-xs leading-6 text-slate-500">Only this fixed receipt can be automated. Reconcile an uncertain send before requesting another. No client/clarification message is sent.</p></section>@else<section class="panel panel-pad"><h2 class="section-title">Email identity assessment</h2><p class="mt-3 text-xs leading-6">Mailbox access and a sender address do not prove customer identity. Review the original message and choose the client explicitly.</p></section>@endif<section class="panel panel-pad"><h2 class="text-base">Possible contact matches</h2><p class="mt-3 text-xs leading-6 text-slate-500">Same email is a review hint. It does not prove the sender belongs to a client.</p>@forelse($matches as $match)<a class="text-link mt-4 block text-xs" href="{{ route('clients.show',$match->client) }}">{{ $match->client->company_name }} · {{ $match->name }}</a>@empty<p class="mt-4 text-xs text-slate-500">No existing contact has this email.</p>@endforelse</section><section class="panel panel-pad"><h2 class="text-base">Possible related inquiries</h2><p class="mt-3 text-xs leading-6 text-slate-500">Same email across channels. Review manually; records are not merged.</p>@forelse($duplicates as $duplicate)<a class="text-link mt-4 block text-xs" href="{{ route('inquiries.show',$duplicate) }}">{{ $duplicate->reference }} · {{ \App\Models\Inquiry::CHANNELS[$duplicate->source_channel] }}</a>@empty<p class="mt-4 text-xs text-slate-500">No other inquiry currently shares this email.</p>@endforelse</section></aside></div></x-layout>
